sysauto_script.script:
// Process pending notifications and fee reminders
var notificationGR = new GlideRecord('x_1843073_institut_notification');
notificationGR.addQuery('sent', false);
notificationGR.addQuery('active', true);
notificationGR.addNullQuery('scheduled_date').addOrCondition('scheduled_date', '<=', gs.nowDateTime());
notificationGR.query();

var notificationCount = 0;
while (notificationGR.next()) {
    // Mark as sent
    notificationGR.setValue('sent', true);
    notificationGR.setValue('sent_date', gs.nowDateTime());
    notificationGR.update();
    notificationCount++;
}

// Check for overdue fees and create notifications
var feeGR = new GlideRecord('x_1843073_institut_fee');
feeGR.addQuery('payment_status', 'pending');
feeGR.addQuery('due_date', '<', gs.nowDate());
feeGR.query();

var overdueCount = 0;
while (feeGR.next()) {
    // Update fee status to overdue
    feeGR.setValue('payment_status', 'overdue');
    feeGR.update();
    overdueCount++;

    // Create overdue fee notification
    var notif = new GlideRecord('x_1843073_institut_notification');
    notif.initialize();
    notif.setValue('title', 'Fee Overdue - ' + feeGR.fee_type.getDisplayValue());
    notif.setValue('message', 'Your ' + feeGR.fee_type.getDisplayValue() + ' of $' + feeGR.getValue('amount') + ' is overdue. Please make payment immediately.');
    notif.setValue('notification_type', 'fee_reminder');
    notif.setValue('priority', 'high');
    notif.setValue('target_audience', 'specific_year');
    notif.setValue('active', true);
    notif.insert();
}

gs.info('Daily notification processing completed. Processed: ' + notificationCount + ' notifications, ' + overdueCount + ' overdue fees');
